export const NET_STEPS=[{"mode":"liberties","form":"basic","title":"İki çıkış, tek hedef","text":"Ağ, Japonca geta; Korece jangmun (장문), Çince jiā (枷). Rakibin çıkışlarını önden kapatan bir yakalama tesujisidir. Önce beyaz taşın iki nefesini tahtada bul."},{"mode":"build","form":"basic","title":"Çaprazdan ağı kur","text":"Beyazın iki nefesinden birine hemen temas etmek yerine, ikisinin de önüne yerleş. Siyah olarak küçük ağı kur; beyazın hâlâ iki nefesi kaldığını gör."},{"mode":"branches","form":"basic","title":"Beyazla ağı sına","text":"Önce beyazla bir çıkıştan uzat, sonra siyahla dışarı açılan yeni nefesi kapat. Renkler sırayla değişecek. İki başlangıç kaçışını da yakalamaya kadar sınamalısın."},{"mode":"pair","form":"pair","title":"İki taşı ağla yakala","text":"Bu kez hedef iki beyaz taş. İki çıkış kolunu tamamlayan ağ hamlesini bul; ardından beyazın üç çıkışını sırayla dene. Siyah her uzayışın dış tarafını kapatarak zinciri yakalayacak."},{"mode":"edge","form":"edge","title":"Kenar ağın bir parçası","text":"Bu iki beyaz taş tahtanın kenarında. Kenarın dışına doğru yeni nefes açılamaz; ancak tahta içine açılan iki çıkış hâlâ okunmalı. Ağı kur ve iki kaçışın da nasıl kapandığını dene."}];
